using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResource
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["environment"] = "production",
        ["version"] = "1.0.0",
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        },
        ["maxRetries"] = 3,
        ["timeoutSeconds"] = 30
    };

    [McpServerResource(UriTemplate = "config://app", Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppConfig() =>
        JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });

    [McpServerResource(UriTemplate = "config://features", Name = "Feature Flags",
        MimeType = "application/json"),
     Description("Returns the current feature flag settings.")]
    public static string GetFeatureFlags() =>
        JsonSerializer.Serialize(AppConfig["features"], new JsonSerializerOptions { WriteIndented = true });
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Check whether a specific feature flag is enabled.")]
    public static string CheckFeature(
        [Description("The feature flag name to check (e.g., darkMode, notifications, betaFeatures)")] string featureName)
    {
        var features = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        };

        if (features.TryGetValue(featureName, out var enabled))
            return $"Feature '{featureName}' is {(enabled ? "enabled" : "disabled")}.";

        return $"Feature '{featureName}' not found. Available: {string.Join(", ", features.Keys)}";
    }

    [McpServerTool, Description("Get the server uptime and health status.")]
    public static string GetHealthStatus()
    {
        return $"Status: healthy | Uptime: {Environment.TickCount64 / 1000}s | Time: {DateTime.UtcNow:O}";
    }
}

